 {page==='Insights'&&<><section className="insights-section-picker" aria-label="Explore your insights"><div className="insights-picker-heading"><span className="eyebrow">EXPLORE YOUR INSIGHTS</span><h2>Two ways to see how far you’ve come</h2><p>Choose a view to explore your habits or the numbers you track.</p></div><div className="insights-view-switch" role="tablist" aria-label="Insights sections"><button role="tab" aria-describedby="insights-consistency-tip" aria-selected={insightsView==='consistency'} aria-controls="insights-panel" onClick={()=>setInsightsView('consistency')}><span className="insights-picker-icon" aria-hidden="true">🗓️</span><span><strong>Your consistency</strong><small>Checkoffs, streaks and routine patterns</small></span><span id="insights-consistency-tip" className="insights-tab-tip" role="tooltip">See how often you followed your scheduled routines, including completed and missed days.</span></button><button role="tab" aria-describedby="insights-progress-tip" aria-selected={insightsView==='progress'} aria-controls="insights-panel" onClick={()=>setInsightsView('progress')}><span className="insights-picker-icon" aria-hidden="true">📈</span><span><strong>Your progress</strong><small>KPIs, measurements and trends</small></span><span id="insights-progress-tip" className="insights-tab-tip" role="tooltip">Explore numbers like steps, miles, water and private measurements—separate from checkoffs.</span></button></div></section><div id="insights-panel" role="tabpanel">{insightsView==='consistency'?<InsightsDashboard owner={owner} today={today} tasks={tasks} settings={settings} completions={completions} earnings={ownerEarnings} kpis={activityKpis} kpiLogs={activityKpiLogs} onOpenRecap={()=>{const d=new Date(today+'T12:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-1);setRecapMonth(d.toISOString().slice(0,7)+'-01')}}/>:<ProgressPage client={supabase} owner={owner} today={today} readOnly={readOnly} tasks={tasks} kpis={activityKpis} kpiLogs={activityKpiLogs}/>}</div></>}
 {page==='Goals'&&<Goals client={supabase} owner={owner} readOnly={readOnly} balance={balance} categories={categories} wishes={wishes} allocations={allocations} itemAllocations={itemAllocations} itemAllocationReady={itemAllocationReady} busy={busy} today={today} onRun={run}/>} 
 {page==='Wallet'&&<Wallet owner={owner} readOnly={readOnly} today={today} earned={totalEarned} spent={totalSpent} balance={balance} earnings={ownerEarnings} purchases={ownerPurchases} busy={busy} error={error} onRun={run}/>}
