 {page==='Profile'&&!readOnly&&<section className="card"><h2>Explore Pronark setup</h2><p>Preview the new-member walkthrough. This will not reset your account or save sample answers.</p><button className="secondary" onClick={()=>setTourOpen(true)}>Explore setup →</button></section>}
 {page==='Profile'&&!readOnly&&<section className="card"><h2>Your groups</h2><p>Choose what each private group can see from you.</p><button className="secondary" onClick={()=>setPage('Groups')}>Open groups →</button></section>}
 {page==='Profile'&&<ProfilePage profile={profiles.find(p=>p.user_id===owner)??ownProfile} readOnly={readOnly} busy={busy} today={today} companion={companion} onCompanion={async choice=>{if(onboardingReady){const saved=await run(()=>rpc('save_experience_preferences',{p_companion:choice,p_chatter:ownExperience?.chatter??'full',p_reduced_motion:ownExperience?.reduced_motion??false,p_expected_revision:ownExperience?.revision??0}),'Companion saved across devices.');if(!saved)return}setCompanion(choice);localStorage.setItem('pronark-companion:'+own,choice)}} onSettings={()=>setPage('Settings')} onEditGoals={()=>setGoalsEditor(true)} onSaveName={(name)=>run(()=>rpc('save_profile_name',{p_name:name,p_expected_revision:ownProfile.revision}),'Profile name saved.')}/>} 
 {page==='Profile'&&!readOnly&&onboardingReady&&<ReactionSettings key={own} client={supabase} tasks={tasks.filter(t=>t.owner_id===own&&!t.archive_date)} preference={ownExperience??null} onRefresh={refresh}/>}
 {page==='Groups'&&<GroupsPage client={supabase} owner={own} tasks={tasks.filter(t=>t.owner_id===own)}/>}
