function PurchaseEditor({purchase,today,balance,busy,error,onClose,onSave,onDelete}:{purchase:Purchase|null;today:string;balance:number;busy:boolean;error:string;onClose:()=>void;onSave:(id:string,title:string,amount:number,date:string,note:string)=>Promise<boolean>;onDelete?:()=>Promise<boolean>}){const [requestId]=useState(()=>crypto.randomUUID()),[title,setTitle]=useState(purchase?.title??''),[amount,setAmount]=useState(purchase?(purchase.amount_cents/100).toFixed(2):''),[date,setDate]=useState(purchase?.purchase_date??today),[note,setNote]=useState(purchase?.note??'');const projected=balance+(purchase?.amount_cents??0)-Math.round(Number(amount)*100);const valid=title.trim()&&/^\d+(\.\d{1,2})?$/.test(amount)&&Number(amount)>0&&date<=today;return <div className="overlay" role="dialog" aria-modal="true"><div className="dialog"><button className="close" onClick={onClose}>×</button><h2>{purchase?'Edit purchase':'Record purchase'}</h2><label>Name<input value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Amount ($)<input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label>Date<input type="date" max={today} value={date} onChange={e=>setDate(e.target.value)}/></label><label>Note (optional)<textarea value={note} onChange={e=>setNote(e.target.value)}/></label>{projected<0&&<p className="banner">This would put your in-app wallet {cents(-projected)} below zero. Pronark is designed for delayed gratification: the immediate win is seeing savings grow. Normal activity rewards repay a deficit; streak bonuses pause until your balance is positive.</p>}{error&&<p role="alert" className="error">{error}</p>}<div className="line"><button className="secondary" onClick={onClose}>Cancel</button><button disabled={busy||!valid} onClick={()=>{if(projected<0&&!confirm('Record this purchase despite the negative wallet warning?'))return;onSave(requestId,title,Math.round(Number(amount)*100),date,note)}}>Save purchase</button></div>{onDelete&&<button className="text-button" disabled={busy} onClick={()=>confirm('Remove this purchase from spending?')&&onDelete()}>Delete purchase</button>}</div></div>}
const goalOrder=['Clothes','Tech','Jewelry','Home items','Experiences','Travel','Other'];
function rewardNotice(before:number,after:number,target:number,name:string){if(target<=0)return 'Savings assigned.';const reached=[25,50,100].filter(m=>before*100<target*m&&after*100>=target*m).at(-1);return reached?`✦ ${name} reached ${reached}% funded! Keep enjoying the progress toward your reward.`:'Savings assigned. Your progress is growing.'}
const goalIcons:Record<string,string>={Clothes:'♧',Tech:'▣',Jewelry:'◇','Home items':'⌂',Experiences:'✧',Travel:'✈',Other:'•••'};
function Goals({client,owner,readOnly,balance,categories,wishes,allocations,itemAllocations,itemAllocationReady,busy,today,onRun}:{client:SupabaseClient;owner:string;readOnly:boolean;balance:number;categories:Category[];wishes:Wish[];allocations:Allocation[];itemAllocations:ItemAllocation[];itemAllocationReady:boolean;busy:boolean;today:string;onRun:(action:()=>Promise<unknown>,message:string)=>Promise<boolean>}){
 const [selectedId,setSelectedId]=useState(''),[editing,setEditing]=useState<Wish|null|undefined>(undefined),[buying,setBuying]=useState<Wish|null>(null),[funding,setFunding]=useState(false),[targetOpen,setTargetOpen]=useState(false),[fundAmount,setFundAmount]=useState(''),[itemFund,setItemFund]=useState<Wish|null>(null),[itemAmount,setItemAmount]=useState(''),[itemSource,setItemSource]=useState<'wallet'|'category'>('wallet');
 const mine=categories.filter(x=>x.owner_id===owner).sort((a,b)=>(a.priority_order??1000)-(b.priority_order??1000)||goalOrder.indexOf(a.category_key)-goalOrder.indexOf(b.category_key));
 const selected=mine.find(x=>x.id===selectedId);
 const allocated=allocations.filter(x=>x.owner_id===owner).reduce((n,x)=>n+x.cents,0),unallocated=balance-allocated;
 const active=(id:string)=>wishes.filter(w=>w.category_id===id&&w.status==='active');
 const saved=(id:string)=>allocations.filter(a=>a.category_id===id).reduce((n,a)=>n+a.cents,0);
 const itemSaved=(id:string)=>itemAllocations.find(a=>a.item_id===id)?.cents??0;
 const freeInCategory=(id:string)=>saved(id)-active(id).reduce((n,w)=>n+itemSaved(w.id),0);
 const items=selected?active(selected.id):[],target=(selected?.general_target_cents??0)+items.reduce((n,w)=>n+w.estimated_cents,0),funded=selected?saved(selected.id):0;
 const percent=(n:number,d:number)=>d>0?Math.min(100,Math.max(0,Math.round(n/d*100))):0;
 const nextUp=mine.map(c=>({category:c,target:(c.general_target_cents??0)+active(c.id).reduce((n,w)=>n+w.estimated_cents,0),amount:saved(c.id)})).filter(x=>x.target>0&&x.amount<x.target).sort((a,b)=>(a.target-a.amount)-(b.target-b.amount))[0];
 return <div className={'goals-page '+(selected?'detail-view':'list-view')}>
 {!selected?<><p className="goals-subtitle">Choose a reward goal of any amount—even more than your wallet holds. Assign the dollars you earn toward it whenever you want.</p><div className="goals-wallet"><div className="wallet-main"><span className="wallet-symbol" aria-hidden="true">▢</span><div><small>Wallet balance</small><strong>{cents(balance)}</strong></div></div><p>Earned dollars assigned {cents(allocated)} <span>·</span> Earned dollars available {cents(Math.max(0,unallocated))}</p></div>{balance<0&&<div className="banner">Your in-app wallet is {cents(-balance)} below zero. Pronark is designed to make saving toward rewards satisfying, not to encourage buying ahead. Activity rewards repay this shortfall; streak bonuses pause until your balance is positive.</div>}{allocated>Math.max(0,balance)&&<div className="banner">Assignments exceed the current wallet by {cents(allocated-Math.max(0,balance))}. New assignments are paused until the balance catches up.</div>}{!itemAllocationReady&&<div className="banner">Item assignments need the new Rewards database migration. Category savings still display.</div>}{nextUp&&<div className="reward-next card"><span>✦ NEXT REWARD IN REACH</span><strong>{nextUp.category.category_key}</strong><p>{cents(nextUp.target-nextUp.amount)} to fully fund · {percent(nextUp.amount,nextUp.target)}% there</p></div>}<div className="goal-grid">{mine.map(c=>{const list=active(c.id),total=(c.general_target_cents??0)+list.reduce((n,w)=>n+w.estimated_cents,0),amount=saved(c.id);return <button type="button" className="card goal-card" key={c.id} onClick={()=>setSelectedId(c.id)}><span className="goal-icon" aria-hidden="true">{goalIcons[c.category_key]??'◦'}</span><span className="goal-card-text"><strong>{c.category_key}</strong>{total>0?<><small>{cents(total)} target · {cents(amount)} saved</small><span className="goal-progress"><span style={{width:percent(amount,total)+'%'}}/></span></>:<small>{cents(0)} target<br/>Set a savings goal of any amount</small>}</span>{total>0&&<small className="goal-percent">{percent(amount,total)}% · {percent(amount,total)>=100?'Funded':percent(amount,total)>=50?'Halfway':percent(amount,total)>=25?'25% milestone':'Getting started'}</small>}<span aria-hidden="true">›</span></button>})}</div>{!mine.length&&<p>Categories are loading. If they stay empty, refresh the page.</p>}</>:<><div className="goal-back-row"><button className="goal-back" onClick={()=>setSelectedId('')} aria-label="Back to goals">‹ <span>Goals</span></button></div><section className="goal-detail"><div className="goal-detail-heading"><span className="goal-icon" aria-hidden="true">{goalIcons[selected.category_key]??'◦'}</span><div><h2>{selected.category_key}</h2><p><strong>{cents(funded)}</strong> earned dollars assigned toward {cents(target)} goal</p></div></div>{!readOnly&&<button className="goal-target-link" onClick={()=>setTargetOpen(true)}>{selected.general_target_cents?'Edit savings goal':'Set savings goal'}</button>}<div className="goal-progress large"><span style={{width:percent(funded,target)+'%'}}/></div><div className="goal-progress-label"><span>{target>0?(percent(funded,target)>=100?'Goal funded ✦':percent(funded,target)>=50?'Next milestone: 100%':percent(funded,target)>=25?'Next milestone: 50%':'Next milestone: 25%'):'Set a target to begin'}</span><strong>{target>0?percent(funded,target)+'%':'—'}</strong></div><p className="reward-breakdown">Category savings goal {cents(selected.general_target_cents??0)} + active items {cents(items.reduce((n,w)=>n+w.estimated_cents,0))} · Free in {selected.category_key}: {cents(Math.max(0,freeInCategory(selected.id)))}</p>{target>0&&<div className="reward-badges" aria-label="Savings milestones">{[25,50,100].map(m=><span key={m} className={funded*100>=target*m?'earned':''}>{funded*100>=target*m?'✦ ':'○ '}{m}%</span>)}</div>}<p className="goal-remaining"><small>Remaining</small><strong>{funded>target?cents(funded-target)+' surplus':cents(Math.max(0,target-funded))}</strong></p>{!readOnly&&<><p className="reward-explainer">Your goal amount is independent of your wallet. Assign the dollars you earn when you are ready; {cents(Math.max(0,unallocated))} is available now.</p><button className="goal-primary" disabled={busy||unallocated<=0} onClick={()=>setFunding(true)}>Assign earned dollars</button></>}<div className="goal-list-heading"><div><h3>Wishlist ({items.length})</h3><p>Items you’re saving for</p></div></div>{items.map(w=><div className="goal-item" key={w.id}><span className="goal-item-icon" aria-hidden="true">{goalIcons[selected.category_key]??'◦'}</span><div className="goal-item-copy"><strong>{w.title}</strong><span>{cents(itemSaved(w.id))} of {cents(w.estimated_cents)} assigned · {percent(itemSaved(w.id),w.estimated_cents)}%</span><span className="goal-progress"><span style={{width:percent(itemSaved(w.id),w.estimated_cents)+'%'}}/></span></div>{!readOnly&&<div className="goal-item-actions"><button className="secondary" disabled={busy||!itemAllocationReady} onClick={()=>{setItemFund(w);setItemAmount('');setItemSource(unallocated>0?'wallet':'category')}}>Assign</button><button className="secondary" disabled={busy} onClick={()=>setBuying(w)}>Record purchase</button><button className="goal-item-next" aria-label={'Edit '+w.title} onClick={()=>setEditing(w)}>›</button></div>}</div>)}{wishes.filter(w=>w.category_id===selected.id&&w.status==='purchased').length>0&&<div className="reward-purchases"><h3>Enjoyed rewards</h3>{wishes.filter(w=>w.category_id===selected.id&&w.status==='purchased').map(w=><p key={w.id}>✦ {w.title} · Purchased</p>)}</div>}{!items.length&&<p className="goal-empty">No items yet. {!readOnly&&'Add an item to save toward a specific reward.'}</p>}{!readOnly&&<button className="goal-add" onClick={()=>setEditing(null)}>＋ &nbsp; Add item</button>}<p className="goal-note">ⓘ &nbsp; Assigning earned dollars tracks your progress; it does not spend them. Your funds stay in your wallet until a purchase.</p></section><GoalTargetPlan key={selected.id} client={client} categoryId={selected.id} today={today} readOnly={readOnly}/></>}
 {selected&&editing!==undefined&&<WishEditor key={editing?.id??'new'} category={selected} item={editing} busy={busy} onClose={()=>setEditing(undefined)} onSave={(title,estimate,url,note)=>onRun(()=>rpc('save_wishlist_item',{p_id:editing?.id??crypto.randomUUID(),p_category:selected.id,p_title:title,p_estimated:estimate,p_url:url||null,p_note:note,p_expected_revision:editing?.revision??null}),'Goal item saved.').then(ok=>{if(ok)setEditing(undefined);return ok})}/>}
 {buying&&<GoalPurchaseEditor key={buying.id} item={buying} today={today} balance={balance} assigned={itemSaved(buying.id)} busy={busy} onClose={()=>setBuying(null)} onSave={(id,title,amount,date,note)=>onRun(()=>rpc('save_purchase',{p_id:id,p_title:title,p_amount_cents:amount,p_date:date,p_note:note,p_wishlist:buying.id,p_expected_revision:null}),'Purchase recorded.').then(ok=>{if(ok)setBuying(null);return ok})}/>} 
 {targetOpen&&selected&&<CategoryTargetEditor key={selected.id} category={selected} itemTotal={items.reduce((n,w)=>n+w.estimated_cents,0)} busy={busy} onClose={()=>setTargetOpen(false)} onSave={(amount)=>onRun(()=>rpc('save_category_target',{p_category:selected.id,p_cents:amount,p_expected_revision:selected.revision}),'General target saved.').then(ok=>{if(ok)setTargetOpen(false);return ok})}/>}
 {funding&&selected&&<div className="overlay" role="dialog" aria-modal="true" aria-label="Assign earned dollars"><div className="dialog"><button className="close" onClick={()=>setFunding(false)} aria-label="Close">×</button><h2>Assign earned dollars to {selected.category_key}</h2><p>Your savings goal can be any amount. You have earned {cents(Math.max(0,unallocated))} that is not yet assigned. Assigning it shows progress without changing your wallet balance.</p><label>Amount ($)<input inputMode="decimal" value={fundAmount} onChange={e=>setFundAmount(e.target.value)} placeholder="0.00"/></label><div className="line"><button className="secondary" onClick={()=>setFunding(false)}>Cancel</button><button disabled={busy||!/^\d+(\.\d{1,2})?$/.test(fundAmount)||Number(fundAmount)<=0||Math.round(Number(fundAmount)*100)>unallocated} onClick={()=>onRun(()=>rpc('fund_category',{p_category:selected.id,p_cents:Math.round(Number(fundAmount)*100),p_move_from:null}),rewardNotice(funded,funded+Math.round(Number(fundAmount)*100),target,selected.category_key)).then(ok=>{if(ok){setFunding(false);setFundAmount('')}})}>Assign earned dollars</button></div></div></div>}{itemFund&&selected&&<div className="overlay" role="dialog" aria-modal="true" aria-label="Assign item savings"><div className="dialog"><button className="close" onClick={()=>setItemFund(null)} aria-label="Close">×</button><h2>Assign to {itemFund.title}</h2><p>Item progress: {cents(itemSaved(itemFund.id))} of {cents(itemFund.estimated_cents)}. Savings stay in your wallet until a purchase is recorded.</p><label>Source<select value={itemSource} onChange={e=>setItemSource(e.target.value as 'wallet'|'category')}><option value="wallet">Earned dollars available · {cents(Math.max(0,unallocated))}</option><option value="category">{selected.category_key} savings · {cents(Math.max(0,freeInCategory(selected.id)))}</option></select></label><label>Amount ($)<input inputMode="decimal" value={itemAmount} onChange={e=>setItemAmount(e.target.value)} placeholder="0.00"/></label><div className="line"><button className="secondary" onClick={()=>setItemFund(null)}>Cancel</button><button disabled={busy||!/^[0-9]+([.][0-9]{1,2})?$/.test(itemAmount)||Number(itemAmount)<=0||Math.round(Number(itemAmount)*100)>(itemSource==='wallet'?unallocated:freeInCategory(selected.id))} onClick={()=>onRun(()=>rpc('assign_item',{p_item:itemFund.id,p_cents:Math.round(Number(itemAmount)*100),p_source:itemSource}),rewardNotice(itemSaved(itemFund.id),itemSaved(itemFund.id)+Math.round(Number(itemAmount)*100),itemFund.estimated_cents,itemFund.title)).then(ok=>{if(ok)setItemFund(null)})}>Assign</button></div>{itemSaved(itemFund.id)>0&&<button className="text-button" disabled={busy||!/^[0-9]+([.][0-9]{1,2})?$/.test(itemAmount)||Number(itemAmount)<=0||Math.round(Number(itemAmount)*100)>itemSaved(itemFund.id)} onClick={()=>onRun(()=>rpc('release_item_savings',{p_item:itemFund.id,p_cents:Math.round(Number(itemAmount)*100)}),'Savings returned to this category.').then(ok=>{if(ok)setItemFund(null)})}>Return this amount to {selected.category_key}</button>}</div></div>}</div>
}
function CategoryTargetEditor({category,itemTotal,busy,onClose,onSave}:{category:Category;itemTotal:number;busy:boolean;onClose:()=>void;onSave:(amount:number)=>Promise<boolean>}){const [amount,setAmount]=useState(((category.general_target_cents??0)/100).toFixed(2));const valid=/^\d+(\.\d{1,2})?$/.test(amount)&&Number(amount)<=1000000;return <div className="overlay" role="dialog" aria-modal="true" aria-label="Savings goal"><div className="dialog"><button className="close" onClick={onClose} aria-label="Close">×</button><h2>{category.category_key} savings goal</h2><p>Set the amount you want to save, even if your wallet has less right now. This goal does not assign or spend earned dollars. Active item goals add {cents(itemTotal)} to this category; purchased items leave that total.</p><label>Amount you want to save ($)<input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="500.00"/></label><div className="line"><button className="secondary" onClick={onClose}>Cancel</button><button disabled={busy||!valid} onClick={()=>onSave(Math.round(Number(amount)*100))}>Save savings goal</button></div></div></div>}
function WishEditor({category,item,busy,onClose,onSave}:{category:Category;item:Wish|null;busy:boolean;onClose:()=>void;onSave:(title:string,estimate:number,url:string,note:string)=>Promise<boolean>}){const [title,setTitle]=useState(item?.title??''),[estimate,setEstimate]=useState(item?(item.estimated_cents/100).toFixed(2):''),[url,setUrl]=useState(item?.external_url??''),[note,setNote]=useState(item?.note??'');return <div className="overlay" role="dialog" aria-modal="true"><div className="dialog"><button className="close" onClick={onClose}>×</button><h2>{item?'Edit item':'Add to '+category.category_key}</h2><label>Name<input value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Estimated cost ($)<input inputMode="decimal" value={estimate} onChange={e=>setEstimate(e.target.value)}/></label><label>Link (optional)<input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://"/></label><label>Notes (optional)<textarea value={note} onChange={e=>setNote(e.target.value)}/></label><div className="line"><button className="secondary" onClick={onClose}>Cancel</button><button disabled={busy||!title.trim()||!/^\d+(\.\d{1,2})?$/.test(estimate)||Number(estimate)<=0||(url!==''&&!/^https?:\/\//.test(url))} onClick={()=>onSave(title,Math.round(Number(estimate)*100),url,note)}>Save item</button></div></div></div>}
function GoalPurchaseEditor({item,today,balance,assigned,busy,onClose,onSave}:{item:Wish;today:string;balance:number;assigned:number;busy:boolean;onClose:()=>void;onSave:(id:string,title:string,amount:number,date:string,note:string)=>Promise<boolean>}){
 const [id]=useState(()=>crypto.randomUUID()),[title,setTitle]=useState(item.title),[amount,setAmount]=useState((item.estimated_cents/100).toFixed(2)),[date,setDate]=useState(today),[note,setNote]=useState('');
 const amountCents=Math.round(Number(amount)*100),early=amountCents>assigned,negative=amountCents>balance;
 return <div className="overlay" role="dialog" aria-modal="true" aria-label="Record purchase"><div className="dialog"><button className="close" onClick={onClose} aria-label="Close">×</button><h2>Record purchase</h2><p>Assigned to this item: {cents(assigned)}. Buying spends from your wallet; any item savings left over stay in the category.</p><label>Name<input value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Actual cost ($)<input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label>Date<input type="date" max={today} value={date} onChange={e=>setDate(e.target.value)}/></label><label>Note (optional)<textarea value={note} onChange={e=>setNote(e.target.value)}/></label>{early&&<p className="banner">This costs {cents(Math.max(0,amountCents-assigned))} more than you assigned to the item. Assign the full amount to this item first. Pronark is designed around the satisfaction of saving toward a goal, not buying ahead.</p>}{negative&&<p className="banner">This would put your in-app wallet {cents(amountCents-balance)} below zero. Normal activity rewards would repay it; streak-bonus progress and payouts pause until the balance is positive. This is not real debt or a money transfer.</p>}<div className="line"><button className="secondary" onClick={onClose}>Cancel</button><button disabled={busy||(early&&!negative)||!title.trim()||!/^\d+(\.\d{1,2})?$/.test(amount)||Number(amount)<=0||date>today} onClick={()=>{if((early||negative)&&!confirm('Record this early purchase despite the savings warning?'))return;onSave(id,title,amountCents,date,note)}}>Save purchase</button></div></div></div>
}
function WeeklyReportSettings({preference,busy,onSaveEmail,onToggleEmail}:{preference?:ReportPreference;busy:boolean;onSaveEmail:(email:string)=>Promise<boolean>;onToggleEmail:(enabled:boolean)=>Promise<boolean>}){const [email,setEmail]=useState(preference?.pending_email??preference?.verified_email??'');return <section className="card settings"><h2>Weekly email report</h2><p>Monday at 6 AM Eastern. Reports only go to a verified address.</p><label>Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><button disabled={busy||!email} onClick={()=>onSaveEmail(email)}>Save and verify email</button><p>{preference?.verification_state==='pending'?'Verification pending — delivery remains disabled.':preference?.verified_email?(preference.enabled?'Weekly email enabled.':'Email verified; weekly email off.'):'No verified email.'}</p>{preference?.verified_email&&<button className="secondary" disabled={busy} onClick={()=>onToggleEmail(!preference.enabled)}>{preference.enabled?'Turn off weekly email':'Turn on weekly email'}</button>}</section>}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
